def _check_company_consistency(self):
    for rule in self:
        route = rule.route_id
        if route.company_id and route.company_id not in rule.company_id.parent_ids:
            raise ValidationError(_(
                "Rule %(rule)s belongs to %(rule_company)s while the route belongs to %(route_company)s.",
                rule=rule.display_name,
                rule_company=rule.company_id.display_name,
                route_company=route.company_id.display_name,
            ))

def _onchange_route(self):
    """ Ensure that the rule's company is the same than the route's company. """
    if self.route_id.company_id:
        self.company_id = self.route_id.company_id
    if self.picking_type_id.warehouse_id.company_id != self.route_id.company_id:
        self.picking_type_id = False

def _get_message_dict(self):
    """ Return a dict with the different possible message used for the
    rule message. It should return one message for each stock.rule action
    (except push and pull). This function is override in mrp and
    purchase_stock in order to complete the dictionary.
    """
    message_dict = {}
    source, destination, direct_destination, operation = self._get_message_values()
    if self.action in ('push', 'pull', 'pull_push'):
        suffix = ""
        if self.action in ('pull', 'pull_push') and direct_destination and not self.location_dest_from_rule:
            suffix = _("<br>The products will be moved towards <b>%(destination)s</b>, <br/> as specified from <b>%(operation)s</b> destination.", destination=direct_destination, operation=operation)
        if self.procure_method == 'make_to_order' and self.location_src_id:
            suffix += _("<br>A need is created in <b>%s</b> and a rule will be triggered to fulfill it.", source)
        if self.procure_method == 'mts_else_mto' and self.location_src_id:
            suffix += _("<br>If the products are not available in <b>%s</b>, a rule will be triggered to bring the missing quantity in this location.", source)
        message_dict = {
            'pull': _(
                'When products are needed in <b>%(destination)s</b>, <br> <b>%(operation)s</b> are created from <b>%(source_location)s</b> to fulfill the need. %(suffix)s',
                destination=destination,
                operation=operation,
                source_location=source,
                suffix=suffix,
            ),
            'push': _(
                'When products arrive in <b>%(source_location)s</b>, <br> <b>%(operation)s</b> are created to send them to <b>%(destination)s</b>.',
                source_location=source,
                operation=operation,
                destination=destination,
            ),
        }
    return message_dict

def _create_mto_rule_if_not_exist(self, vals):
    route_exists = self.env['stock.rule'].search_count([
        ('route_id', '=', vals.get('route_id', False)),
        ('location_src_id', '=', vals.get('location_src_id', False)),
        ('location_dest_id', '=', vals.get('location_dest_id', False)),
        ('picking_type_id', '=', vals.get('picking_type_id', False)),
        ('procure_method', '=', vals.get('procure_method', False)),
    ], limit=1)
    if not route_exists:
        self.env['stock.rule'].create(vals)

def _serialize_procurement_values(self, values):
    """Helper method to serialize procurement values for storage.

    This method handles the serialization of different types of values:
    - BaseModel instances are converted to their IDs
    - Datetime and Date fields are converted to strings
    - Other values are kept as is

    :param values: Dictionary of procurement values
    :return: Dictionary with serialized values
    """
    serialized = {}
    for key, value in values.items():
        if isinstance(value, models.BaseModel):
            serialized[key] = value.ids
        elif isinstance(value, (datetime.datetime, datetime.date)):
            serialized[key] = value.isoformat()
        elif isinstance(value, (fields.Datetime, fields.Date)):
            serialized[key] = fields.Datetime.to_string(value) if isinstance(value, fields.Datetime) else fields.Date.to_string(value)
        else:
            serialized[key] = value
    return serialized

def run(self, procurements, raise_user_error=True):
    """Fulfil `procurements` with the help of stock rules.

    Procurements are needs of products at a certain location. To fulfil
    these needs, we need to create some sort of documents (`stock.move`
    by default, but extensions of `_run_` methods allow to create every
    type of documents).

    :param procurements: the description of the procurement
    :type procurements: list of `~odoo.addons.stock.models.stock_rule.ProcurementGroup.Procurement`
    :param raise_user_error: will raise either an UserError or a ProcurementException
    :type raise_user_error: boolan, optional
    :raises UserError: if `raise_user_error` is True and a procurement isn't fulfillable
    :raises ProcurementException: if `raise_user_error` is False and a procurement isn't fulfillable
    """

    def raise_exception(procurement_errors):
        if raise_user_error:
            dummy, errors = zip(*procurement_errors)
            raise UserError('\n'.join(errors))
        else:
            raise ProcurementException(procurement_errors)
    actions_to_run = defaultdict(list)
    procurement_errors = []
    for procurement in procurements:
        procurement.values.setdefault('company_id', procurement.location_id.company_id)
        procurement.values.setdefault('priority', '0')
        procurement.values.setdefault('date_planned', procurement.values.get('date_planned', False) or fields.Datetime.now())
        if self._skip_procurement(procurement):
            continue
        rule = self._get_rule(procurement.product_id, procurement.location_id, procurement.values)
        if not rule:
            error = _('No rule has been found to replenish "%(product)s" in "%(location)s".\nVerify the routes configuration on the product.',
                product=procurement.product_id.display_name, location=procurement.location_id.display_name)
            procurement_errors.append((procurement, error))
        else:
            action = 'pull' if rule.action == 'pull_push' else rule.action
            actions_to_run[action].append((procurement, rule))

    if procurement_errors:
        raise_exception(procurement_errors)

    for action, procurements in actions_to_run.items():
        if hasattr(self.env['stock.rule'], '_run_%s' % action):
            try:
                getattr(self.env['stock.rule'], '_run_%s' % action)(procurements)
            except ProcurementException as e:
                procurement_errors += e.procurement_exceptions
        else:
            _logger.error("The method _run_%s doesn't exist on the procurement rules" % action)

    if procurement_errors:
        raise_exception(procurement_errors)
    return True

def _search_rule_for_warehouses(self, route_ids, packaging_uom_id, product_id, warehouse_ids, company_id, domain):
    domain = Domain(domain)
    if warehouse_ids:
        domain &= Domain('warehouse_id', 'in', [False, *warehouse_ids.ids])
    valid_route_ids = set()
    if route_ids:
        valid_route_ids |= set(route_ids.ids)
    if packaging_uom_id:
        packaging_routes = packaging_uom_id.package_type_id.route_ids
        valid_route_ids |= set(packaging_routes.ids)
    valid_route_ids |= set((product_id.route_ids | product_id.categ_id.total_route_ids).ids)
    if warehouse_ids:
        filter_function = partial(self._filter_warehouse_routes, product_id, warehouse_ids)
        valid_route_ids |= set(warehouse_ids.route_ids.filtered(filter_function).ids)
    if valid_route_ids:
        domain &= Domain('route_id', 'in', list(valid_route_ids))
    res = self.env["stock.rule"].sudo()._read_group(  # sudo() needed for cross company warehouse usage
        domain,
        groupby=["location_dest_id", "warehouse_id", "route_id"],
        aggregates=["id:recordset"],
        order="route_sequence:min, sequence:min",
    )
    rule_dict = defaultdict(OrderedDict)
    for group in res:
        rules = group[3]
        if filtered_rules := rules.filtered(lambda r: company_id and r.company_id == company_id):
            rules = filtered_rules

        rule_dict[group[0].id, group[2].id][group[1].id] = rules.sorted(lambda rule: (rule.route_sequence, rule.sequence))[0]
    return rule_dict

def _search_rule(self, route_ids, packaging_uom_id, product_id, warehouse_id, domain):
    """ First find a rule among the ones defined on the procurement
    group, then try on the routes defined for the product, finally fallback
    on the default behavior
    """
    Rule = self.env['stock.rule']
    res = self.env['stock.rule']
    domain = Domain(domain)
    if warehouse_id:
        domain &= Domain('warehouse_id', 'in', [False, warehouse_id.id])
    domain = domain.optimize(Rule)
    if route_ids:
        res = Rule.search(Domain('route_id', 'in', route_ids.ids) & domain, order='route_sequence, sequence', limit=1)
    if not res and packaging_uom_id:
        packaging_routes = packaging_uom_id.package_type_id.route_ids
        if packaging_routes:
            res = Rule.search(Domain('route_id', 'in', packaging_routes.ids) & domain, order='route_sequence, sequence', limit=1)
    if not res:
        product_routes = product_id.route_ids | product_id.categ_id.total_route_ids
        if product_routes:
            res = Rule.search(Domain('route_id', 'in', product_routes.ids) & domain, order='route_sequence, sequence', limit=1)
    if not res and warehouse_id:
        warehouse_routes = warehouse_id.route_ids
        if warehouse_routes:
            res = Rule.search(Domain('route_id', 'in', warehouse_routes.ids) & domain, order='route_sequence, sequence', limit=1)
    elif not res and not warehouse_id:
        res = Rule.search(domain, order='route_sequence, sequence', limit=1)
    return res

def _check_intercomp_location(self, locations):
    if locations.filtered(lambda location: location.usage == 'transit'):
        inter_comp_location = self.env.ref('stock.stock_location_inter_company', raise_if_not_found=False)
        return inter_comp_location and inter_comp_location.id in locations.ids

def run_scheduler(self, use_new_cursor=False, company_id=False):
    """ Call the scheduler in order to check the running procurements (super method), to check the minimum stock rules
    and the availability of moves. This function is intended to be run for all the companies at the same time, so
    we run functions as SUPERUSER to avoid intercompanies and access rights issues. """
    try:
        self._run_scheduler_tasks(use_new_cursor=use_new_cursor, company_id=company_id)
    except Exception:
        _logger.error("Error during stock scheduler", exc_info=True)
        raise
    return {}

def _get_orderpoint_domain(self, company_id=False):
    domain = [('trigger', '=', 'auto'), ('product_id.active', '=', True)]
    if company_id:
        domain += [('company_id', '=', company_id)]
    return domain

def warehouse_location(self):
    if self.type == 'purchase':
        return self.location

@Override
public void processNonCompliantStockLocationLine(
    StockRules stockRules, StockLocationLine stockLocationLine) throws AxelorException {

  if (stockRules == null) {
    return;
  }

  if (stockRules.getOrderAlertSelect().equals(StockRulesRepository.ORDER_ALERT_ALERT)) {
    this.generateAndSendMessage(stockRules);
    return;
  }

  StockLocation stockLocation = stockLocationLine.getStockLocation();

  if (stockLocation == null
      || !appSupplychainService.isApp("supplychain")
      || !stockRules
          .getOrderAlertSelect()
          .equals(StockRulesRepository.ORDER_ALERT_PURCHASE_ORDER)) {
    return;
  }

  Product product = stockLocationLine.getProduct();

  BigDecimal minReorderQty = getDefaultSupplierMinQty(product);
  BigDecimal qtyToOrder =
      stockRulesService.getQtyToOrder(stockLocationLine, stockRules, minReorderQty);
  Partner supplierPartner = product.getDefaultSupplierPartner();

  if (supplierPartner != null) {

    Company company = stockLocation.getCompany();
    LocalDate today = appBaseService.getTodayDate(company);
    PurchaseOrder purchaseOrder =
        purchaseOrderRepo.save(
            purchaseOrderCreateSupplychainService.createPurchaseOrder(
                AuthUtils.getUser(),
                company,
                null,
                supplierPartner.getCurrency(),
                today.plusDays(supplierPartner.getDeliveryDelay()),
                stockRules.getName(),
                null,
                stockLocation,
                today,
                partnerPriceListService.getDefaultPriceList(
                    supplierPartner, PriceListRepository.TYPE_PURCHASE),
                supplierPartner,
                null,
                null));

    purchaseOrder.addPurchaseOrderLineListItem(
        purchaseOrderLineService.createPurchaseOrderLine(
            purchaseOrder, product, null, null, qtyToOrder, product.getUnit()));

    purchaseOrderService.computePurchaseOrder(purchaseOrder);

    purchaseOrderRepo.save(purchaseOrder);

    if (stockRules.getAlert()) {
      generateAndSendMessage(stockRules);
    }
  }
}

def validate_duplicate_rule(self):
	existing_rule = frappe.db.exists(
		"Putaway Rule", {"item_code": self.item_code, "warehouse": self.warehouse}
	)
	if existing_rule and existing_rule != self.name:
		frappe.throw(
			_("Putaway Rule already exists for Item {0} in Warehouse {1}.").format(
				frappe.bold(self.item_code), frappe.bold(self.warehouse)
			),
			title=_("Duplicate"),
		)

def validate_priority(self):
	if self.priority < 1:
		frappe.throw(_("Priority cannot be lesser than 1."), title=_("Invalid Priority"))

def validate_warehouse_and_company(self):
	company, is_group, disabled = frappe.db.get_value(
		"Warehouse", self.warehouse, ["company", "is_group", "disabled"]
	)
	if (is_group or disabled) and not self.disable:
		frappe.throw(
			_("Warehouse {0} must be an enabled warehouse that is not a group.").format(
				frappe.bold(self.warehouse)
			),
			title=_("Invalid Warehouse"),
		)

	if not self.disable and not frappe.get_cached_value("Item", self.item_code, "is_stock_item"):
		frappe.throw(_("Item {0} is not a stock item.").format(frappe.bold(self.item_code)))

	if company != self.company:
		frappe.throw(
			_("Warehouse {0} does not belong to Company {1}.").format(
				frappe.bold(self.warehouse), frappe.bold(self.company)
			),
			title=_("Invalid Warehouse"),
		)

def validate_capacity(self):
	stock_uom = frappe.db.get_value("Item", self.item_code, "stock_uom")
	balance_qty = _get_stock_balance(self.item_code, self.warehouse, nowdate())

	if flt(self.stock_capacity) < flt(balance_qty):
		frappe.throw(
			_(
				"Warehouse Capacity for Item '{0}' must be greater than the existing stock level of {1} {2}."
			).format(self.item_code, frappe.bold(balance_qty), stock_uom),
			title=_("Insufficient Capacity"),
		)

	if not self.capacity:
		frappe.throw(_("Capacity must be greater than 0"), title=_("Invalid"))

def apply_putaway_rule(
	doctype: str,
	items: InstanceOf[list] | str,
	company: str,
	sync: str | bool | None = None,
	purpose: str | None = None,
):
	if doctype not in ("Purchase Receipt", "Stock Entry"):
		_refuse()
	frappe.has_permission(doctype, "write", throw=True)
	allowed_companies = get_allowed_docs_for_doctype(
		get_user_permissions(frappe.session.user).get("Company", []), doctype
	)
	if allowed_companies and company not in allowed_companies:
		_refuse()
	if not frappe.has_permission("Item", "read"):
		return

	return _apply_putaway_rule(doctype, items, company, sync, purpose)

def get_ordered_putaway_rules(item_code, company, source_warehouse=None):
	"""Returns an ordered list of putaway rules to apply on an item."""
	return select_vacant_rules(get_item_putaway_rules(item_code, company), source_warehouse)

def select_vacant_rules(rules, source_warehouse=None):
	rules = [rule for rule in rules if rule.warehouse != source_warehouse]
	if not rules:
		return False, None

	vacant_rules = [rule for rule in rules if rule.free_space > 0]
	if not vacant_rules:
		return True, None

	return False, sorted(vacant_rules, key=lambda rule: (rule.priority, -rule.free_space))

def reorder_item():
	"""Reorder item if stock reaches reorder level"""
	# if initial setup not completed, return
	if not (frappe.db.a_row_exists("Company") and frappe.db.a_row_exists("Fiscal Year")):
		return

	if cint(frappe.db.get_single_value("Stock Settings", "auto_indent")):
		return _reorder_item()

def _reorder_item():
	material_requests = {"Purchase": {}, "Transfer": {}, "Material Issue": {}, "Manufacture": {}}
	warehouse_company = frappe._dict(
		frappe.db.sql(
			"""select name, company from `tabWarehouse`
		where disabled=0"""
		)
	)
	default_company = (
		erpnext.get_default_company() or frappe.db.sql("""select name from tabCompany limit 1""")[0][0]
	)

	items_to_consider = get_items_for_reorder()

	if not items_to_consider:
		return

	item_warehouse_projected_qty = get_item_warehouse_projected_qty(items_to_consider)

	def add_to_material_request(**kwargs):
		if isinstance(kwargs, dict):
			kwargs = frappe._dict(kwargs)

		if kwargs.warehouse not in warehouse_company:
			# a disabled warehouse
			return

		reorder_level = flt(kwargs.reorder_level)
		reorder_qty = flt(kwargs.reorder_qty)

		# projected_qty will be 0 if Bin does not exist
		if kwargs.warehouse_group:
			projected_qty = flt(
				item_warehouse_projected_qty.get(kwargs.item_code, {}).get(kwargs.warehouse_group)
			)
		else:
			projected_qty = flt(item_warehouse_projected_qty.get(kwargs.item_code, {}).get(kwargs.warehouse))

		original_reorder_qty = reorder_qty
		if (reorder_level or reorder_qty) and projected_qty <= reorder_level:
			if projected_qty + reorder_qty <= reorder_level:
				reorder_qty += reorder_level - projected_qty

			company = warehouse_company.get(kwargs.warehouse) or default_company

			material_requests[kwargs.material_request_type].setdefault(company, []).append(
				{
					"item_code": kwargs.item_code,
					"warehouse": kwargs.warehouse,
					"reorder_qty": reorder_qty,
					"item_details": kwargs.item_details,
					"projected_on_hand": projected_qty,
					"reorder_level": reorder_level,
					"original_reorder_qty": original_reorder_qty,
				}
			)

	for item_code, reorder_levels in items_to_consider.items():
		for d in reorder_levels:
			if d.has_variants:
				continue

			add_to_material_request(
				item_code=item_code,
				warehouse=d.warehouse,
				reorder_level=d.warehouse_reorder_level,
				reorder_qty=d.warehouse_reorder_qty,
				material_request_type=d.material_request_type,
				warehouse_group=d.warehouse_group,
				item_details=frappe._dict(
					{
						"item_code": item_code,
						"name": item_code,
						"item_name": d.item_name,
						"item_group": d.item_group,
						"brand": d.brand,
						"description": d.description,
						"stock_uom": d.stock_uom,
						"purchase_uom": d.purchase_uom,
						"lead_time_days": d.lead_time_days,
					}
				),
			)

	if material_requests:
		return create_material_request(material_requests)

def get_item_warehouse_projected_qty(items_to_consider):
	item_warehouse_projected_qty = {}
	items_to_consider = list(items_to_consider.keys())

	warehouse_parent_map = frappe._dict(
		frappe.get_all("Warehouse", fields=["name", "parent_warehouse"], as_list=True)
	)

	for item_code, warehouse, projected_qty in frappe.db.sql(
		"""select item_code, warehouse, projected_qty
		from tabBin where item_code in ({})
			and (warehouse != '' and warehouse is not null)""".format(
			", ".join(["%s"] * len(items_to_consider))
		),
		items_to_consider,
	):
		if item_code not in item_warehouse_projected_qty:
			item_warehouse_projected_qty.setdefault(item_code, {})

		if warehouse not in item_warehouse_projected_qty.get(item_code):
			item_warehouse_projected_qty[item_code][warehouse] = flt(projected_qty)

		parent_warehouse = warehouse_parent_map.get(warehouse)

		while parent_warehouse:
			if not item_warehouse_projected_qty.get(item_code, {}).get(parent_warehouse):
				item_warehouse_projected_qty.setdefault(item_code, {})[parent_warehouse] = flt(projected_qty)
			else:
				item_warehouse_projected_qty[item_code][parent_warehouse] += flt(projected_qty)
			parent_warehouse = warehouse_parent_map.get(parent_warehouse)

	return item_warehouse_projected_qty

@Override
public boolean useMinStockRules(
    StockLocationLine stockLocationLine, StockRules stockRules, int type) {

  Pair<BigDecimal, BigDecimal> qtyPair =
      getCurrentQtySumAndFutureQtySumOfProductInStockLocationAndItsContainedStockLocations(
          stockRules.getStockLocation(), stockRules.getProduct());
  BigDecimal currentQty = qtyPair.getLeft();
  BigDecimal futureQty = qtyPair.getRight();

  BigDecimal minQty = stockRules.getMinQty();

  if (type == StockRulesRepository.TYPE_CURRENT) {
    if (currentQty.compareTo(minQty) < 0) {
      return true;
    }
  } else if (type == StockRulesRepository.TYPE_FUTURE) {
    if (futureQty.compareTo(minQty) < 0) {
      return true;
    }
  }
  return false;
}

@Override
public StockRules getStockRules(
    Product product, StockLocation stockLocation, int type, int useCase) {
  Set<Long> stockLocationIds =
      stockLocationService.getLocationAndAllParentLocationsIdsOrderedFromTheClosestToTheFurthest(
          stockLocation);

  StockRules stockRules = null;
  if (useCase == StockRulesRepository.USE_CASE_USED_FOR_MRP) {
    String filter =
        "self.product = :product AND self.stockLocation.id = :stockLocationId AND self.useCaseSelect = :useCase";
    /* We use this for statement and not a query with `in List` in it so that we can get the
    first stockRule that is the closest to the stockLocation given in the parameter.*/
    for (Long stockLocationId : stockLocationIds) {
      stockRules =
          stockRuleRepo
              .all()
              .filter(filter)
              .bind("product", product)
              .bind("stockLocationId", stockLocationId)
              .bind("useCase", useCase)
              .fetchOne();
      if (stockRules != null) {
        break;
      }
    }
  } else if (useCase == StockRulesRepository.USE_CASE_STOCK_CONTROL) {
    String filter =
        "self.product = :product AND self.stockLocation.id = :stockLocationId AND self.useCaseSelect = :useCase AND self.typeSelect = :type";
    /* We use this for statement and not a query with `in List` in it so that we can get the
    first stockRule that is the closest to the stockLocation given in the parameter.*/
    for (Long stockLocationId : stockLocationIds) {
      stockRules =
          stockRuleRepo
              .all()
              .filter(filter)
              .bind("product", product)
              .bind("stockLocationId", stockLocationId)
              .bind("useCase", useCase)
              .bind("type", type)
              .fetchOne();
      if (stockRules != null) {
        break;
      }
    }
  }
  return stockRules;
}
